CREATE INDEX IF NOT EXISTS idx_embedding_retirement_queue ON embedding_retirement_queue(project_id,model_key,updated_at,id);

CREATE TRIGGER IF NOT EXISTS embedding_versions_retirement_insert AFTER INSERT ON embedding_versions BEGIN
        DELETE FROM embedding_retirement_queue WHERE (project_id,model_key,id) IN
    (SELECT project_id,model_key,id FROM embedding_receipts WHERE project_id=NEW.project_id AND type=NEW.type AND record_id=NEW.record_id);
    INSERT INTO embedding_retirement_queue(project_id,model_key,id,updated_at)
    SELECT r.project_id,r.model_key,r.id,r.updated_at FROM embedding_receipts r WHERE project_id=NEW.project_id AND type=NEW.type AND record_id=NEW.record_id
      AND r.ready>=0 AND NOT EXISTS (SELECT 1 FROM embedding_versions v
  WHERE v.project_id=r.project_id AND v.type=r.type AND v.record_id=r.record_id
    AND v.revision=r.revision AND ((v.type = 'session' AND EXISTS (SELECT 1 FROM sessions
    WHERE project_id = v.project_id AND session_id = v.record_id AND (summary IS NOT NULL AND trim(summary) <> ''))) OR (v.type = 'spore' AND EXISTS (SELECT 1 FROM spores
    WHERE project_id = v.project_id AND id = v.record_id AND (status = 'active'))) OR (v.type = 'plan' AND EXISTS (SELECT 1 FROM plans
    WHERE project_id = v.project_id AND plan_key = v.record_id AND (content IS NOT NULL OR (blob_key IS NOT NULL AND EXISTS (
  SELECT 1 FROM processed_resources pr WHERE pr.project_id = plans.project_id AND pr.kind = 'plan'
    AND pr.resource_id = plans.plan_key AND pr.blob_key = plans.blob_key AND pr.classification = 'processed')))))))
  AND NOT EXISTS(SELECT 1 FROM embedding_models k WHERE k.project_id=r.project_id AND k.model_key=r.model_key AND k.active=0);
         END;

